      <button type="button" class="email-modal-close" id="closeEmailModal" aria-label="Close" onclick="toggleEmailModal(false)" style="position: absolute; top: 16px; right: 16px; width: 32px; height: 32px; border-radius: 50%; background: rgba(255, 255, 255, 0.25); border: none; color: #ffffff; font-size: 24px; line-height: 1; display: flex; align-items: center; justify-content: center; cursor: pointer; z-index: 10;">&times;</button>
